from 写入第二遍 import add
add('25_002',2,'16:9，青侧面胸上近景占画面右半，面朝画面左侧，左下留出她将要看的地面方向；固定机位。','青刚吸进的气停在唇边，握紧的手在画外顿住；她先把眼睛转向画外左下方的石铺地面，再跟着转头，嘴唇从紧绷松开成疑惑的小口形。那声疑问落下后，她下巴稍低，视线停在地面一点，汗还留在脸侧。','铅蓝云天在上侧，左下只见虚化的灰绿石铺地面和薄米灰落尘。','上方云天冷白柔光，地面弱中性反光。','呼气中途停住，地面传来细小而不规则的湿响，远处低风持续。',ja=['ん？'],tone='忽然被地面动静牵住，短而带疑问。',kind='mixed',phase='reaction',node={'青.阶段':'注意转到画外左下方地面'},card={'opening':'她还处在愤怒的余势里。','beats':['吸气停住，眼睛先转下','头跟上，疑问口形形成'],'coupling':'新的地面动静打断骂声后的情绪。','landing':'视线停在液团所在位置，观众尚未看到其变化。'})
add('25_003',2.5,'16:9，略俯的液团中近景，白色团块位于画面中央下方，边缘与石缝同时可见；镜头由团边慢慢推向鼓包，落幅仍不揭出小体全貌。','落地液团的边缘先抖动，一处圆包慢慢鼓高，又像被下面推着向另一侧移；旁边两个小包接着顶起，细长突起弯下再竖起。整团白色物质起伏越来越密，边缘拖着地面收拢，最后鼓到将要撑开的形状。','灰绿石铺地面贴着团块延伸，深灰缝隙清楚，后方地面虚化并压成深灰绿色。','上方云天冷白漫射在白色表面形成柔亮边，凹陷处偏浅灰。','不规则湿黏鼓动声，由间断转为密集，边缘贴石面轻轻粘拉。',phase='process',node={'白色液团.阶段':'地面鼓动、分裂前'},meaning='保留液团鼓包与弯曲突起，尚不提前显示之后小体的完整头尾。')
add('26_001',.5,'16:9，正上方俯视全景，液团在画面中央，石地占满周围；固定机位，白色爆散形向上下左右伸出。','液团短促收紧后猛然向多方向撑开，中心变成尖锐白色团形，几道长白尾和小液滴同时向外围甩出；石面没有新增破裂，白色小形从中心离开时仍只读成一片爆散轮廓。','灰绿不规则石铺地面与深灰缝隙平铺整个背景，爆散白形之间始终露出地面。','上方云天冷白漫射，白色重音保持纸白质感，环境亮度稳定。','一次短促液体爆裂声，细小滴落噼啪散向各处。',phase='process',node={'白色液团.阶段':'整体爆散、内部小体尚未完整揭晓'},meaning='原作液团爆散的俯视过渡节点保留；没有新增爆炸威力或石面破坏。')
